import JSON

"""
	halfnormal_excess_kurtosis()

Returns the excess kurtosis of a half-normal distribution.
"""
function halfnormal_excess_kurtosis()
	return 8 * (pi - 3) / (pi - 2)^2
end

"""
	gen( sigma, name )

Generate fixture data and write to file.

# Arguments

* `sigma`: standard deviation
* `name::AbstractString`: output filename
"""
function gen( sigma, name )
	κ = halfnormal_excess_kurtosis()
	z = fill( κ, length(sigma) )

	data = Dict(
		"sigma" => sigma,
		"expected" => z
	)

	filepath = joinpath( dir, name )

	open(filepath, "w") do outfile
		write(outfile, JSON.json(data))
		write(outfile, "\n")
	end
end

# Get the filename:
file = @__FILE__

# Extract the directory in which this file resides:
dir = dirname(file)

# Generate fixtures:
sigma = rand(10) .* 5.0
gen(sigma, "data.json")
